/// <summary>
/// Maps the entity to the backing datasources.
/// </summary>
/// <param name = "entityCtx">The context of the entity.</param>
/// <param name = "dataSourceCtx">The context of the datasource being mapped.</param>
public void mapEntityToDataSource(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
{
    if (_dataSourceCtx.name() == dataEntityDataSourceStr(METLedgerJournalGlobalEntity, LedgerJournalTable))
    {
        LedgerJournalTable ledgerJournalTable = this.resolveLedgerJournalTable();
        this.LedgerJournalTableRecId = ledgerJournalTable.RecId;

        _dataSourceCtx.setBuffer(ledgerJournalTable);
    }

    // When editing through the entity, always delay tax calculation to avoid
    // a O(n^2) tax calculation while importing multiple lines. The journal will
    // automatically calculate taxes later at posting time or when necessary.
    this.DelayTaxCalculation = NoYes::Yes;

    super(_entityCtx, _dataSourceCtx);
}

private LedgerJournalTable resolveLedgerJournalTable()
{
    if (!this.LedgerJournalTableRecId)
    {
        //TODO: Revisit this line of code while upgrading to 10.0.41
        this.LedgerJournalTableRecId = this.getLedgerJournalTableByGroup(this.METJournalGroup).RecId;
    }

    LedgerJournalTable ledgerJournalTable;

    if (!this.LedgerJournalTableRecId)
    {
        ledgerJournalTable.JournalName = this.JournalName;
        ledgerJournalTable.initFromLedgerJournalName();
        ledgerJournalTable.insert();

        this.LedgerJournalTableRecId = ledgerJournalTable.RecId;
    }

    ledgerJournalTable = LedgerJournalTable::findByRecId(this.LedgerJournalTableRecId);

    this.JournalBatchNumber = ledgerJournalTable.JournalNum;

    return ledgerJournalTable;
}

private LedgerJournalTable getLedgerJournalTableByGroup(str _journalGroupId)
{
    LedgerJournalTable ledgerJournalTable;

    //TODO:Revisit code in 10.0.41
    //Field added METJournalGroup to the data entity and referenced in code
    select ledgerJournalTable
        where ledgerJournalTable.METJournalGroup == _journalGroupId
        && ledgerJournalTable.Posted == NoYes::No;

    return ledgerJournalTable;
}

public boolean validateWrite()
{
    boolean isValid = this.isJournalValid();

    if (isValid)
    {
        // skip setting default dimension display value if it is blank otherwise isFieldSet will set to true and further we can't set default dimension as it remains blank
        if (this.DefaultDimensionDisplayValue != '')
        {
            this.DefaultDimensionDisplayValue = METLedgerJournalGlobalEntity::validateDefaultDimensionDisplayValueIsNonLedgerType(this.AccountType, this.DefaultDimensionDisplayValue);
        }

        if (this.OffsetDefaultDimensionDisplayValue != '')
        {
            this.OffsetDefaultDimensionDisplayValue = METLedgerJournalGlobalEntity::validateDefaultDimensionDisplayValueIsNonLedgerType(this.OffsetAccountType, this.OffsetDefaultDimensionDisplayValue, true);
        }

        isValid = super();
    }

    return isValid;
}

/// <summar
/// Warns if the default dimension is set when the account type is ledger.
/// </summary>
/// <param name = "_accountType">The account type.</param>
/// <param name = "_displayValue">The default dimension display value.</param>
/// <param name = "_isOffset">true if checking the offset field, otherwise, false.</param>
/// <returns>The resulting default dimension display value.</returns>
internal static DimensionDisplayValue validateDefaultDimensionDisplayValueIsNonLedgerType(DimensionAccountType _accountType, DimensionDisplayValue _displayValue, boolean _isOffset = false)
{
    DimensionDisplayValue result = _displayValue;

    if (_accountType == LedgerJournalACType::Ledger && _displayValue != '')
    {
        FieldName displayValueFieldName = _isOffset ? fieldPName(METLedgerJournalGlobalEntity, OffsetDefaultDimensionDisplayValue) : fieldPName(METLedgerJournalGlobalEntity, DefaultDimensionDisplayValue);
        FieldName accountTypeFieldName = _isOffset ? fieldPName(METLedgerJournalGlobalEntity, OffsetAccountType) : fieldPName(METLedgerJournalGlobalEntity, AccountType);

        // Don't fail, only throw a warning.
        warning(strFmt("@GeneralLedger:JournalEntityDimensionsOnLedgerAccount",
            displayValueFieldName,
            accountTypeFieldName,
            enum2Str(LedgerJournalACType::Ledger)));

        result = '';
    }

    return result;
}

public boolean validateDelete()
{
    boolean isValid = this.isJournalValid();;

    if (isValid)
    {
        isValid = super();
    }

    return isValid;
}

public boolean insertEntityDataSource(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
{
    LedgerJournalTransTaxExtension ledgerJournalTransTaxExtension = METLedgerJournalGlobalEntity::setLedgerJournalTransTaxExtension(_dataSourceCtx);

    if (_dataSourceCtx.name() == dataEntityDataSourceStr(METLedgerJournalGlobalEntity, LedgerJournalTrans))
    {
        METLedgerJournalGlobalEntity entity = _entityCtx.getEntityRecord();
        LedgerJournalTrans ledgerJournalTrans = _dataSourceCtx.getBuffer();

        this.resolveFinTags(entity, ledgerJournalTrans);
    }

    boolean ret = super(_entityCtx, _dataSourceCtx);

    if (ret && _dataSourceCtx.name() == dataEntityDataSourceStr(METLedgerJournalGlobalEntity, LedgerJournalTrans))
    {
        LedgerJournalTrans ledgerJournalTrans = _dataSourceCtx.getBuffer();

        LedgerJournalEngine_Server::adjustDate(ledgerJournalTrans);

        LedgerJournalEngine::determineCashDiscountForEntities(ledgerJournalTrans);

        ttsbegin;
        ledgerJournalTrans.setSettleVoucher();
        ledgerJournalTrans.doUpdate();
        ttscommit;
    }

    // When <c>LedgerJournalTransTaxExtension</c> is not inserted successfully and it links well with <c>LedgerJournalTrans</c>,
    // it should try to insert/update the table <c>LedgerJournalTransTaxExtension</c> with set value.
    if (!ret && ledgerJournalTransTaxExtension.LedgerJournalTrans)
    {
        ttsbegin;
        LedgerJournalTrans ledgerJournalTrans = ledgerJournalTransTaxExtension.getLedgerJournalTrans();
        ledgerJournalTransTaxExtension.save(ledgerJournalTrans, true);
        ttscommit;

        ret = true;
    }

    METLedgerJournalGlobalEntity::saveDataSource(_dataSourceCtx);

    return ret;
}

public boolean updateEntityDataSource(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
{
    LedgerJournalTrans ledgerJournalTransOrig;

    if (_dataSourceCtx.name() == dataEntityDataSourceStr(METLedgerJournalGlobalEntity, LedgerJournalTrans))
    {
        ledgerJournalTransOrig = _dataSourceCtx.getBuffer().orig();

        METLedgerJournalGlobalEntity entity = _entityCtx.getEntityRecord();
        LedgerJournalTrans ledgerJournalTrans = _dataSourceCtx.getBuffer();

        this.resolveFinTags(entity, ledgerJournalTrans);
    }

    boolean ret = super(_entityCtx, _dataSourceCtx);

    if (ret && dataEntityDataSourceStr(METLedgerJournalGlobalEntity, LedgerJournalTrans) == _dataSourceCtx.name())
    {
        LedgerJournalTrans ledgerJournalTrans = _dataSourceCtx.getBuffer();

        LedgerJournalEngine_Server::adjustDate(ledgerJournalTrans);

        LedgerJournalEngine::determineCashDiscountForEntities(ledgerJournalTrans, ledgerJournalTransOrig);
    }

    METLedgerJournalGlobalEntity::saveDataSource(_dataSourceCtx);

    return ret;
}

internal static void saveDataSource(DataEntityDataSourceRuntimeContext _dataSourceCtx)
{
    METLedgerJournalGlobalEntity lineEntity;
    if (_dataSourceCtx.name() == tableStr(LedgerJournalTrans) && lineEntity.checkShouldUpdateJournalHeaderBalance())
    {
        LedgerJournalTrans ledgerJournalTrans = _dataSourceCtx.getBuffer() as LedgerJournalTrans;

        // update the journal balances
        LedgerJournalTable ledgerJournalTable = LedgerJournalTable::find(ledgerJournalTrans.JournalNum);

        ledgerJournalTable.updateBalances();
    }
}

/// <summary>
/// Determines if the journal header balance should be updated during a journal line write event.
/// </summary>
/// <returns>true if the journal header balance should be updated, otherwise, false.</returns>
/// <remarks>
/// Provides a hook to override/opt out of the default behavior of updating the journal header balance with each line
/// write.  Once a platform deliverable is available allowing a hook for a post publish event to update the balance only
/// once, this will be a no-op.
///
/// If the customer opts out of the header balance updated - the journal balance will not be updated on the excel template,
/// but this does not impact the journal balance displayed on the form.
/// </remarks>
private boolean checkShouldUpdateJournalHeaderBalance()
{
    boolean shouldUpdateBalance = true;

    EventHandlerResult result = new EventHandlerResult();

    this.shouldUpdateJournalHeaderBalance(result);

    if (result.hasResult())
    {
        shouldUpdateBalance = result.result();
    }

    return shouldUpdateBalance;
}

/// <summary>
/// Raises an event providing a subsciber the option to opt out of the journal header balance
/// update with each journal line write.
/// </summary>
/// <param name = "_result">The <c>EventHandlerResult</c> instance.</param>
delegate void shouldUpdateJournalHeaderBalance(EventHandlerResult _result)
{
}

/// <summary>
/// Gets a custom account type lookup serialized string for the Account type field.
/// </summary>
/// <returns>A serialized string with a list of account types.</returns>
[
    SysODataActionAttribute("LedgerJournalGlobalEntityAccountTypeFieldCustomLookup", false),
    SysODataCollectionAttribute("_fields", Types::String),
    SysODataFieldLookupAttribute("AccountType")
]
public static str accountTypeCustomLookup(Array _fields)
{
    OfficeAppCustomLookupListResult result = new OfficeAppCustomLookupListResult();
    result.determinationFields().value(1, fieldStr(METLedgerJournalGlobalEntity, AccountType));

    int current = 1;

    Set supportedTypes = new LedgerDailyJournalExcelTemplate().supportedAccountTypes();
    SetEnumerator supportedTypesEnumerator = supportedTypes.getEnumerator();

    while (supportedTypesEnumerator.moveNext())
    {
        LedgerJournalACType currentACType = supportedTypesEnumerator.current();
        result.items().value(current, enum2Str(currentACType));
        current++;
    }

    return result.serialize();
}

